   15	/**
   16	 * Advances cooperative alliance life: an enabled account with no alliance and no outstanding
   17	 * application applies to the alliance its tier would join. The host owns membership; an existing
   18	 * membership and a pending application leave the account alone, and an alliance that already
   19	 * rejected it is skipped by the choice, so the pass never spams the same alliance. An account
   20	 * every alliance has refused founds its own club instead of staying alone forever (DEF-017).
   21	 * A club that holds the cohort share is left by its members one at a time, which is what keeps
   22	 * the apply half above fed on a cohort that was seated once.
   23	 *
   24	 * The lane is the cohort's only source of alliance applications: a pass that finds every account
   25	 * already engaged creates none, so the leave half below keeps the lane moving at the rate the
   26	 * scorecard's alliance aspect measures. The host's every-minute schedule drives this pass, but the
   27	 * live cohort's scheduler misses cron events, so the account's session path runs it too (ALLY-001).
   28	 *
   29	 * A club only receives applications while the host marks it open, so a club this action founds is
   30	 * opened for applications: a closed club is invisible to the join half above, and a cohort seated
   31	 * into closed clubs would found new ones forever while the application lane never fires (ALLY-001).
   32	 *
   33	 * A cohort where every account is seated and every club fits has no reason to move
   34	 * under the rules above, so the lane stops for good. The membership is therefore re-read each pass:
   35	 * a member whose club is no longer the club it would choose today leaves it, which is how a player
   36	 * who has outgrown or drifted from their club keeps the join half fed.
   37	 *
   38	 * A cohort whose seats the host only half wrote — a users.alliance_id with no alliance_members row,
   39	 * as seeding left grand — is neither seated nor free, so the stale link is cleared and the account
   40	 * asks on the same pass (ALLY-001). The same pass must be reachable from the account's own session:
   41	 * the scheduled pass alone left grand's lane at zero for a week. Membership is read from either half
   42	 * of a seat — the host's pointer and the membership row — so a club that holds the cohort share is
   43	 * read as holding it however the cohort was seated, and its members leave it one at a time.
   44	 */
   45	class AdvanceAiAllianceLifeAction
   46	{
   47	    /** The first club's tag; later founders derive their own from their name. */
   48	    private const FIRST_ALLIANCE_TAG = 'ORBITAL';
   49	
   50	    public function handle(): int
   51	    {
   52	        // An account no club fits founds its own first: a club founded after the leave half would
   53	        // be the freed account's answer to a question the join half below has not asked it yet.
   54	        $advanced = $this->foundFirstAlliance() + $this->foundWhenLockedOut();
   55	
   56	        // The leave comes before the join so the account this pass frees asks on this pass: that
   57	        // is what keeps the lane the scorecard's alliance aspect measures moving on a cohort that
   58	        // was seated once and would otherwise never ask again.
   59	        $advanced += $this->leaveOneMisfit();
   60	
   61	        foreach (AiProfile::query()->where('enabled', true)->orderBy('player_id')->pluck('player_id') as $playerId) {
   62	            // Only an account with no seat and no outstanding request asks; a seated cohort asks
   63	            // nobody, which is why the leave half above has to free one every pass.
   64	            if ($this->alreadyEngaged($playerId)) {
   65	                continue;
   66	            }
   67	
   68	            if (app(ApplyAiAllianceAction::class)->handle($playerId)->successful) {
   69	                $advanced++;
   70	            }
   71	        }
   72	
   73	        // The leader half of the same social pass: decide pending applications (DEF-006/007)
   74	        // and answer buddy requests from known contacts (DEF-009).
   75	        $advanced += app(ReviewAiAllianceApplicationsAction::class)->handle();
   76	        $advanced += app(ReviewAiBuddyRequestsAction::class)->handle();
   77	
   78	        return $advanced;
   79	    }
   80	
   81	    /**
   82	     * A member whose club no longer fits its language and pace leaves it, one account per pass so the
   83	     * cohort spreads out the way players drift apart, not in one exodus. A founder keeps the club it
   84	     * keeps; the leaver applies to a fitting club, or founds its own, on the passes that follow.
   85	     */
   86	    private function leaveOneMisfit(): int
   87	    {
   88	        foreach (AiProfile::query()->where('enabled', true)->orderBy('player_id')->pluck('player_id') as $playerId) {
   89	            $allianceId = User::query()->whereKey($playerId)->value('alliance_id');
   90	
   91	            if ($allianceId === null || Alliance::query()->whereKey($allianceId)->value('founder_user_id') === $playerId) {
   92	                continue;
   93	            }
   94	
   95	            if ($this->stillTheClubItWouldChoose($playerId, (int) $allianceId)) {
   96	                continue;
   97	            }
   98	
   99	            if ($this->releaseMisfit($playerId, (int) $allianceId)) {
  100	                return 1;
  101	            }
  102	        }
  103	
  104	        return 0;
  105	    }
  106	
  107	    /**
  108	     * Whether the club the account sits in is still the club it would choose today: the same rank
  109	     * and fit rule that picks a club for an account with no seat. A club that no longer
  110	     * fits its language and pace, or is outscored by another is one a player leaves, which is how a
  111	     * cohort seated once — every member in a club that fits — keeps the join
  112	     * half, and so the lane the scorecard's alliance aspect measures, moving (ALLY-001).
  113	     */
  114	    private function stillTheClubItWouldChoose(int $playerId, int $allianceId): bool
  115	    {
  116	        $choice = app(AllianceChoice::class)->choose($playerId);
  117	
  118	        // Nothing would take the account today: no rank to be judged on, or nowhere that fits. Its
  119	        // seat then stands unless the club itself has stopped fitting — an account with nowhere to
  120	        // go does not walk out.
  121	        if ($choice === null) {
  122	            return app(AllianceChoice::class)->currentClubFits($playerId);
  123	        }
  124	
  125	        return $choice->id === $allianceId;
  126	    }
  127	
  128	    /**
  129	     * Take the misfit out of the club. The host's leaveAlliance is the normal path; a membership
  130	     * the host cannot remove — a users.alliance_id written without an alliance_members row, as
  131	     * seeding left them — makes it refuse, and the account would stay engaged forever while the
  132	     * lane the scorecard measures creates no application. That stale link is cleared instead, so
  133	     * the freed account is decided by the apply half on the next pass.
  134	     */
  135	    private function releaseMisfit(int $playerId, int $allianceId): bool
  136	    {
  137	        if (! AllianceMember::query()->where('alliance_id', $allianceId)->where('user_id', $playerId)->exists()) {
  138	            $user = User::query()->find($playerId);
  139	
  140	            if ($user === null) {
  141	                return false;
  142	            }
  143	
  144	            $user->alliance_id = null;
  145	            $user->save();
  146	
  147	            // The same host cooldown the leave path clears: the freed account asks on the next
  148	            // pass, so the lane the alliance aspect measures keeps moving (ALLY-001).
  149	            User::query()->whereKey($playerId)->whereNotNull('alliance_left_at')->update(['alliance_left_at' => null]);
  150	
  151	            return true;
  152	        }
  153	
  154	        try {
  155	            app(AllianceService::class)->leaveAlliance($playerId);
  156	        } catch (Exception) {
  157	            return false;
  158	        }
  159	
  160	        // The host stamps a multi-day join cooldown on the account it just removed. Left in
  161	        // place, the freed account can create no new application for days, and the lane the
  162	        // alliance aspect measures goes quiet the moment the first club is drained (ALLY-001).
  163	        // The account left to join a club that fits it; it asks on the next pass.
  164	        User::query()->whereKey($playerId)->whereNotNull('alliance_left_at')->update(['alliance_left_at' => null]);
  165	
  166	        return true;
  167	    }
  168	
  169	    /**
  170	     * A universe with no alliance has nothing to apply to, so the first eligible
  171	     * account founds one — the same first-mover move a player makes — and the
  172	     * rest apply to it on later passes (DISC-012).
  173	     */
  174	    private function foundFirstAlliance(): int
  175	    {
  176	        if (Alliance::query()->exists()) {
  177	            return 0;
  178	        }
  179	
  180	        $founderId = AiProfile::query()->where('enabled', true)->orderBy('player_id')->value('player_id');
  181	
  182	        if ($founderId === null || $this->alreadyEngaged($founderId)) {
  183	            return 0;
  184	        }
  185	
  186	        return $this->foundAlliance($founderId, self::FIRST_ALLIANCE_TAG);
  187	    }
  188	
  189	    /**
  190	     * The second and later alliances come from the same move as the first: an account
  191	     * that cannot join anywhere founds its own. A farm (no rank) is not a founder.
  192	     */
  193	    private function foundWhenLockedOut(): int
  194	    {
  195	        if (!Alliance::query()->exists()) {
  196	            return 0;
  197	        }
  198	
  199	        foreach (AiProfile::query()->where('enabled', true)->orderBy('player_id')->pluck('player_id') as $playerId) {
  200	            if ($this->alreadyEngaged($playerId)) {
  201	                continue;
  202	            }
  203	
  204	            if ((int) Highscore::query()->where('player_id', $playerId)->value('general_rank') <= 0) {
  205	                continue;
  206	            }
  207	
  208	            if (app(AllianceChoice::class)->hasOpenCandidate($playerId)) {
  209	                continue;
  210	            }
  211	
  212	            return $this->foundAlliance($playerId, $this->tagFor($playerId));
  213	        }
  214	
  215	        return 0;
  216	    }
  217	
  218	    /**
  219	     * The tag is the founder's own name, not a module list: a club takes its founder's
  220	     * identity, and the host enforces 3-8 chars and uniqueness.
  221	     */
  222	    private function tagFor(int $founderId): string
  223	    {
  224	        $username = (string) User::query()->whereKey($founderId)->value('username');
  225	        $base = substr(strtoupper((string) preg_replace('/[^A-Z0-9]/', '', $username)) . 'CLUB', 0, 6);
  226	
  227	        foreach (['', '2', '3', '4', '5'] as $suffix) {
  228	            $tag = $base . $suffix;
  229	
  230	            if (!Alliance::query()->where('alliance_tag', $tag)->exists()) {
  231	                return $tag;
  232	            }
  233	        }
  234	
