14	/**
15	 * Runs one session work item.
16	 *
17	 * The conversation cycle is composed here, where the session's own work is composed,
18	 * rather than inside the scheduling service: the session answers what is pending and then
19	 * decides what to do, and the scheduling service keeps depending on nothing but its own
20	 * domain.
21	 */
22	class RunAiSessionAction implements RunAiSession
23	{
24	    public function __construct(
25	        private SessionDecisionService $sessionDecisionService,
26	        private ScheduleAiIntentAction $scheduleAiIntentAction,
27	        private AiClock $clock,
28	        private PlayerGameStateService $playerGameStateService,
29	    ) {
30	    }
31	
32	    public function handle(AiProfile $profile, AiWorkItem $workItem): void
33	    {
34	        // Scheduled actors have no HTTP page load to advance completed host queues. Use the host
35	        // seam without stamping activity when the session later decides to do nothing.
36	        if (User::query()->whereKey($profile->player_id)->exists()) {
37	            $player = $this->playerGameStateService->advance($profile->player_id, null, false);
38	
39	            // advance() drains the queues of the player's current planet alone; every other planet
40	            // is advanced only on a page visit that never happens for a scheduled actor. A colony the
41	            // account settles therefore fills its five queue slots and stays full forever, so it never
42	            // builds a shipyard, a ship or a defence. Drain each remaining planet the same way the
43	            // host's own page load does.
44	            if ($player->planets->all() !== []) {
45	                $currentPlanetId = $player->planets->current()->getPlanetId();
46	
47	                foreach ($player->planets->all() as $planet) {
48	                    if ($planet->getPlanetId() === $currentPlanetId) {
49	                        continue;
50	                    }
51	
52	                    $planet->update();
53	                }
54	            }
55	        }
56	
57	        // A message is answered when the account next wakes, not when it next thinks about
58	        // its economy: sessions are 34 to 56 minutes apart, and that is the whole window a
59	        // reply has to fit inside. The alliance lane rides the same wake below.
60	        if (app(AiRuntimeSettings::class)->conversationEnabled()) {
61	            app(RunAiConversationCycleAction::class)->handle($profile->player_id, $this->clock->now());
62	        }
63	
64	        // The alliance lane has its own every-minute scheduled pass, and the live cohort's harness
65	        // never fires it: the lane created no application in a week while the sessions ran fine
66	        // (ALLY-001). The account's session drives it here, as it drives the conversation cycle
67	        // above, so one pass per login keeps the lane the scorecard's alliance aspect measures
68	        // asking, deciding and moving.
69	        app(AdvanceAiAllianceLifeAction::class)->handle();
70	
71	
72	        // The decision is recorded first and the intent scheduled from what it recorded, so a
73	        // session whose choice cannot be carried out still leaves the trace of what it wanted.
74	        $trace = $this->sessionDecisionService->run($profile, $workItem);
75	        $this->scheduleAiIntentAction->handle($profile, $workItem, $trace);
76	    }
77	}

